// Normalize webhook body and validate ACK payload
const input = $input.first().json;
const body = input.body ?? input;

// Required fields
const command_id = body.command_id;
const device_id = body.device_id;
const status = body.status;

if (!command_id) throw new Error('Missing command_id');
if (!device_id) throw new Error('Missing device_id');
if (!status) throw new Error('Missing status');

// Validate status is SUCCESS or FAILED
const validStatuses = ['SUCCESS', 'FAILED'];
if (!validStatuses.includes(status)) {
  throw new Error('Invalid status: ' + status + '. Must be SUCCESS or FAILED.');
}

// UUID format validation for command_id
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuidRegex.test(command_id)) {
  throw new Error('Invalid command_id format');
}

// If SUCCESS, actual_state must be present
if (status === 'SUCCESS' && !body.actual_state) {
  throw new Error('SUCCESS ACK must include actual_state');
}

return [{
  json: {
    command_id: command_id,
    device_id: device_id,
    device_code: body.device_code ?? undefined,
    status: status,
    actual_state: body.actual_state ?? undefined,
    message: body.message ?? undefined,
    sequence: body.sequence ?? undefined,
    observed_at: body.observed_at ?? new Date().toISOString()
  }
}];

const response = $input.first().json;
const statusCode = response.statusCode ?? 200;
const responseBody = response.body ?? response;

// Handle HTTP error responses from backend
if (statusCode >= 400) {
  return [{
    json: {
      success: false,
      command_id: $('Validate ACK Payload').first().json.command_id,
      device_id: $('Validate ACK Payload').first().json.device_id,
      http_status: statusCode,
      error: responseBody.message ?? 'Backend returned error',
      error_type: statusCode === 404 ? 'COMMAND_NOT_FOUND' :
                  statusCode === 400 ? 'VALIDATION_ERROR' :
                  statusCode === 409 ? 'CONFLICT' : 'BACKEND_ERROR',
      ack_status: $('Validate ACK Payload').first().json.status,
      needs_incident: false
    }
  }];
}

// Parse successful response
const result = typeof responseBody === 'string' ? JSON.parse(responseBody) : responseBody;

return [{
  json: {
    success: true,
    command_id: result.command_id ?? $('Validate ACK Payload').first().json.command_id,
    device_id: $('Validate ACK Payload').first().json.device_id,
    ok: result.ok,
    status: result.status,
    duplicate: result.duplicate ?? false,
    late: result.late ?? false,
    applied: result.applied !== undefined ? result.applied : true,
    ack_status: $('Validate ACK Payload').first().json.status,
    needs_incident: $('Validate ACK Payload').first().json.status === 'FAILED'
  }
}];

// FAILED ACK → create incident candidate for WF10
const ack = $input.first().json;
return [{
  json: {
    incident_candidate: true,
    type: 'COMMAND_FAILED',
    severity: 'HIGH',
    dedup_key: 'cmd-failed-' + ack.command_id,
    room: 'A101',
    device_id: ack.device_id,
    command_id: ack.command_id,
    evidence: {
      ack_status: 'FAILED',
      message: $('Validate ACK Payload').first().json.message ?? 'Device reported failure',
      observed_at: $('Validate ACK Payload').first().json.observed_at
    },
    recovered: false,
    source: 'WF05'
  }
}];

// LATE_ACK → create incident candidate for WF10
const ack = $input.first().json;
return [{
  json: {
    incident_candidate: true,
    type: 'LATE_ACK',
    severity: 'MEDIUM',
    dedup_key: 'late-ack-' + ack.command_id,
    room: 'A101',
    device_id: ack.device_id,
    command_id: ack.command_id,
    evidence: {
      ack_status: ack.ack_status,
      late: true,
      applied: ack.applied,
      observed_at: $('Validate ACK Payload').first().json.observed_at
    },
    recovered: false,
    source: 'WF05'
  }
}];

// SUCCESS ACK → normal completion
const ack = $input.first().json;
return [{
  json: {
    success: true,
    command_id: ack.command_id,
    device_id: ack.device_id,
    status: 'ACK',
    duplicate: ack.duplicate,
    message: ack.duplicate
      ? 'Duplicate ACK ignored safely'
      : 'Command acknowledged successfully, actual_state updated',
    processed_at: new Date().toISOString()
  }
}];

// ACK processing failed at backend level
const ack = $input.first().json;
return [{
  json: {
    success: false,
    command_id: ack.command_id,
    device_id: ack.device_id,
    error: ack.error,
    error_type: ack.error_type,
    http_status: ack.http_status,
    message: 'Backend rejected ACK. Check command_id, device_id and sequence.',
    processed_at: new Date().toISOString()
  }
}];
